changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.drop_tenant_partitions(p_tenant text) RETURNS integer
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
SET lock_timeout = '10s'
AS $fn$
DECLARE
    c_attempts  CONSTANT integer := 5;
    v_dropped   integer := 0;
    v_prev      text;
    v_attempt   integer := 0;
    v_locked    boolean := false;
    v_locked_at timestamptz;
    v_oids      oid[] := ARRAY[]::oid[];
    v_targets   text[] := ARRAY[]::text[];
    v_deps      text[];
    r           record;
BEGIN
    IF p_tenant IS NULL THEN
        RAISE EXCEPTION 'nexus.drop_tenant_partitions: a tenant is required'
            USING ERRCODE = 'null_value_not_allowed';
    END IF;
    IF p_tenant = 'default' THEN
        RAISE EXCEPTION 'nexus.drop_tenant_partitions: the default tenant is never dropped'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    -- The same advisory lock create_tenant_partitions takes: a creation and a drop for one tenant serialize.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('nexus.create_tenant_partitions:' || p_tenant, 0));

    -- The tenant's model partitions and leaves, found by partition bound and read from the catalog alone, BEFORE any
    -- table lock: a tenant with none (a typo, or a repeat) is answered here, locking nothing. The loop below takes
    -- them in this order, and so does the lock step.
    FOR r IN
        SELECT mn.nspname::text AS mp_ns, mp.relname::text AS mp_name, mp.oid AS mp_oid,
               ln.nspname::text AS leaf_ns, lc.relname::text AS leaf_name, lc.oid AS leaf_oid
          FROM pg_catalog.pg_class par
          JOIN pg_catalog.pg_namespace pn ON pn.oid = par.relnamespace AND pn.nspname = 'nexus'
          JOIN pg_catalog.pg_inherits i1 ON i1.inhparent = par.oid
          JOIN pg_catalog.pg_class mp ON mp.oid = i1.inhrelid
          JOIN pg_catalog.pg_namespace mn ON mn.oid = mp.relnamespace
          JOIN pg_catalog.pg_inherits i2 ON i2.inhparent = mp.oid
          JOIN pg_catalog.pg_class lc ON lc.oid = i2.inhrelid
          JOIN pg_catalog.pg_namespace ln ON ln.oid = lc.relnamespace
         WHERE par.relname IN ('chunks', 'taxonomy_centroids')
           AND nexus.partition_bound_value(lc.oid) = p_tenant
         ORDER BY par.relname, mp.relname
    LOOP
        v_oids := v_oids || ARRAY[r.mp_oid, r.leaf_oid];
        v_targets := v_targets || ARRAY[pg_catalog.format('ONLY %I.%I', r.mp_ns, r.mp_name),
                                        pg_catalog.format('ONLY %I.%I', r.leaf_ns, r.leaf_name)];
    END LOOP;
    IF pg_catalog.cardinality(v_oids) = 0 THEN
        RETURN 0;
    END IF;

    -- Every other table a DETACH or DROP of those partitions takes ACCESS EXCLUSIVE on: the tables that have a foreign
    -- key to them (the manifest, topic assignments, orphaned-at records) and the tables they have one to (the
    -- collection registry), found from pg_constraint so a foreign key added later is covered without editing this.
    SELECT COALESCE(pg_catalog.array_agg(q.name ORDER BY q.name), ARRAY[]::text[]) INTO v_deps
      FROM (SELECT DISTINCT pg_catalog.format('%I.%I', dn.nspname, d.relname) AS name
              FROM pg_catalog.pg_constraint con
              JOIN pg_catalog.pg_class d
                ON d.oid = CASE WHEN con.conrelid = ANY (v_oids) THEN con.confrelid ELSE con.conrelid END
              JOIN pg_catalog.pg_namespace dn ON dn.oid = d.relnamespace
             WHERE con.contype = 'f'
               AND (con.conrelid = ANY (v_oids) OR con.confrelid = ANY (v_oids))
               AND NOT d.oid = ANY (v_oids)
               AND d.oid NOT IN (SELECT t.relid FROM pg_catalog.pg_partition_tree('nexus.chunks'::pg_catalog.regclass) t)
               AND d.oid NOT IN (SELECT t.relid FROM pg_catalog.pg_partition_tree('nexus.taxonomy_centroids'::pg_catalog.regclass) t)) q;

    v_prev := pg_catalog.current_setting('nexus.tenant', true);
    PERFORM pg_catalog.set_config('nexus.tenant', p_tenant, true);
    -- Manifest rows first: their foreign key to the chunks does not cascade, and deleting them stamps
    -- chunk_orphaned_at for the chunks it releases, which is why that table is cleared last.
    DELETE FROM nexus.catalog_document_chunks WHERE tenant_id = p_tenant;
    DELETE FROM nexus.topic_assignments WHERE tenant_id = p_tenant;
    DELETE FROM nexus.chunk_orphaned_at WHERE tenant_id = p_tenant;
    PERFORM pg_catalog.set_config('nexus.tenant', COALESCE(v_prev, ''), true);

    -- Every lock the teardown needs, ACCESS EXCLUSIVE, in one bounded attempt: (1) the tables around the leaves, (2)
    -- the two roots, ONLY (no recursion into other tenants' leaves, whose index builds and vacuums would make the
    -- drop fail for nothing), (3) this tenant's own model partitions and leaves, ONLY, in the order the loop takes
    -- them. A search takes the root, then the manifest tables; a writer takes a manifest table, then the root; no one
    -- order matches both. What keeps either safe is the bound: every acquisition waits at most 500 ms, below
    -- deadlock_timeout (1 s), so the drop gives up (lock_not_available) before PostgreSQL's deadlock detector can
    -- choose a search or a writer as its victim. A failed attempt rolls its subtransaction back, which releases what
    -- it took; the three DELETEs above ran outside it. The drop sleeps 0.2 s x attempt between attempts, holding
    -- nothing, and gives up after five.
    PERFORM pg_catalog.set_config('lock_timeout', '500ms', true);
    WHILE NOT v_locked LOOP
        v_attempt := v_attempt + 1;
        BEGIN
            IF pg_catalog.cardinality(v_deps) > 0 THEN
                EXECUTE 'LOCK TABLE ' || pg_catalog.array_to_string(v_deps, ', ') || ' IN ACCESS EXCLUSIVE MODE';
            END IF;
            LOCK TABLE ONLY nexus.chunks, ONLY nexus.taxonomy_centroids IN ACCESS EXCLUSIVE MODE;
            EXECUTE 'LOCK TABLE ' || pg_catalog.array_to_string(v_targets, ', ') || ' IN ACCESS EXCLUSIVE MODE';
            v_locked := true;
        EXCEPTION WHEN lock_not_available THEN
            IF v_attempt >= c_attempts THEN
                RAISE EXCEPTION 'nexus.drop_tenant_partitions(%): gave up after % attempts: a search, a manifest write, an index build or a vacuum on this tenant''s partitions held a lock it needs; rerun, after index builds finish if one is running',
                    p_tenant, c_attempts
                    USING ERRCODE = 'lock_not_available';
            END IF;
            PERFORM pg_catalog.pg_sleep(0.2 * v_attempt);
        END;
    END LOOP;
    v_locked_at := pg_catalog.clock_timestamp();

    -- Everything the loop touches is already held, so lock_timeout stays at 500 ms: a lock that was somehow missed
    -- aborts the call instead of holding the roots for the function's 10 s.
    BEGIN
        FOR r IN
            SELECT mn.nspname::text AS mp_ns, mp.relname::text AS mp_name,
                   ln.nspname::text AS leaf_ns, lc.relname::text AS leaf_name
              FROM pg_catalog.pg_class par
              JOIN pg_catalog.pg_namespace pn ON pn.oid = par.relnamespace AND pn.nspname = 'nexus'
              JOIN pg_catalog.pg_inherits i1 ON i1.inhparent = par.oid
              JOIN pg_catalog.pg_class mp ON mp.oid = i1.inhrelid
              JOIN pg_catalog.pg_namespace mn ON mn.oid = mp.relnamespace
              JOIN pg_catalog.pg_inherits i2 ON i2.inhparent = mp.oid
              JOIN pg_catalog.pg_class lc ON lc.oid = i2.inhrelid
              JOIN pg_catalog.pg_namespace ln ON ln.oid = lc.relnamespace
             WHERE par.relname IN ('chunks', 'taxonomy_centroids')
               AND nexus.partition_bound_value(lc.oid) = p_tenant
             ORDER BY par.relname, mp.relname
        LOOP
            EXECUTE pg_catalog.format('ALTER TABLE %I.%I DETACH PARTITION %I.%I',
                                      r.mp_ns, r.mp_name, r.leaf_ns, r.leaf_name);
            EXECUTE pg_catalog.format('DROP TABLE %I.%I', r.leaf_ns, r.leaf_name);
            v_dropped := v_dropped + 1;
        END LOOP;
    EXCEPTION WHEN lock_not_available THEN
        RAISE EXCEPTION 'nexus.drop_tenant_partitions(%): a lock the detach needs beyond those taken up front was held; nothing was dropped; rerun, after index builds finish if one is running',
            p_tenant
            USING ERRCODE = 'lock_not_available';
    END;
    -- The hold is measured to this point; the locks are held until the caller's COMMIT, so inside a longer
    -- transaction the stall is longer than reported.
    RAISE NOTICE 'nexus.drop_tenant_partitions(%): locks taken on attempt % of %, held % ms to function return (they stay held until the caller''s COMMIT), % leaves dropped',
        p_tenant, v_attempt, c_attempts,
        pg_catalog.round(1000 * EXTRACT(epoch FROM pg_catalog.clock_timestamp() - v_locked_at)::numeric, 1),
        v_dropped;
    RETURN v_dropped;
END
$fn$;

